#### Core Methods Implementation

#### 1. **Two-Body System (Sun/Planet Example)**
##### `phys/orbital_engine.cpp`
```cpp
#include "orbital_engine.h"
#include <functional>
#include <iostream>

// === Physical Constants ===
const double PhysicalConstants::G = 6.67430e-11; // gravitational constant
const double PhysicalConstants::AU = 1.495976e11;     // 1 Solar Orbital Period
const double PhysicalConstants::METERS_AU = 149597870700.0; // 1 AU in meters

// Inverse of sum of masses (for two-body), for small dt velocities and positions
double twoBodyInverseM(double mass1, double mass2) {
    return 1.0 / mass1 + 1.0 / mass2;
}

double OrbitalEngine::calculateStep(double dt) {
    // Accumulate sum of inverse masses for all bodies (needed for two-body, or for N-body as seen below)
    for (int i = 1; i < bodies_.size(); ++i)
        invM_[i] = 1.0 / bodies_[i]->mass;

    for (int i = 0; i < bodies_.size() - 1; ++i) {
        const CelestialBody* current = &bodies_[i];
        const CelestialBody* next    = &bodies_[i+1];

        // mutual perturbation acceleration
        Vector2D deltaPos = next->position - current->position;
        double R = std::norm(deltaPos);
        if (R > PhysicalConstants::AU * 1.0000001) {
            // Ignore external influences for simplicity in a basic N-body integrator
            Vector2D acc = deltaPos * invM[i] * PhysicalConstants::G / (R*R);
            next->velocity += acc; 
            current->velocity -= acc; 
        }

        // Advance by dt (Verlet integration, simple acceleration):
        current->position += current->velocity * dt;
        current->velocity += Vector2D(0, -PhysicalConstants::G / R) * invM[i];
        // Optionally also advance next for more accurate N-body:

        // Verlet update for both bodies
        if (i+1 < bodies_.size()) {
            next->position += next->velocity * dt;
            next->velocity += deltaPos * (invM[i] - invM[i+1]) * PhysicalConstants::G / (R*R);
            next->velocity += (current->position - next->position) * (invM[i] + invM[i+1]) * PhysicalConstants::G / R;
            current->position += current->velocity * dt;
            // reverse perturbation step
            current->velocity += (next->position - current->position) * PhysicalConstants::G * R * (invM[i] - invM[i+1]);
        }
    }
}
```

