#### 2. **N-Body System**

##### `phys/orbital_engine.cpp`
```cpp
double OrbitalEngine::calculateStep(double dt) {
    // Advance all bodies first
    for (CelestialBody* b : bodies_)
        b->position += b->velocity * dt;

    for (size_t i = 1; i < bodies_.size()-1; ++i) {
        const CelestialBody* a = &bodies_[i];
        const CelestialBody* b = &bodies_[i+1];
        Vector2D offset = b->position - a->position;
        double R = std::norm(offset);

        // Compute acceleration due to each mass
        a->velocity += offset * PhysicalConstants::G / (R*R) * (1./a->mass + 1./b->mass);
        b->velocity -= offset * PhysicalConstants::G / (R*R) * (1./b->mass + 1./a->mass);

        // Optional, more accurate method:
        // a->position += a->velocity * dt;
        b->position -= b->velocity * dt;
    }
}
```

